{% if collection.description != blank %}
  <style>
    .iq-collection-intro {
      padding: 12px 20px 0;
    }

    .iq-collection-intro__text {
      max-width: 1180px;
      margin: 0 auto;
      text-align: center;
      font-size: 16px;
      line-height: 1.55;
      color: #444;
    }

    .iq-collection-intro__text p {
      margin: 0 0 6px;
      font-size: inherit;
      line-height: inherit;
    }

    .iq-collection-intro__text p:last-child {
      margin-bottom: 0;
    }

    .iq-collection-intro__text strong,
    .iq-collection-intro__text b {
      font-weight: 500;
    }

    .iq-collection-intro__text a {
      color: inherit;
      font-weight: 500;
      text-decoration: underline;
      text-underline-offset: 3px;
    }

    .iq-collection-intro__text a:hover {
      color: #a51d1b;
    }

    @media (max-width: 749px) {
      .iq-collection-intro__text {
        text-align: left;
        font-size: 14px;
        line-height: 1.5;
      }

      .iq-collection-intro__text strong,
      .iq-collection-intro__text b {
        font-weight: 400;
      }
    }
  </style>

  <div class="iq-collection-intro">
    <div class="iq-collection-intro__text">
      {{ collection.description }}
    </div>
  </div>
{% endif %}

{% if collection.handle == 'hundesport-jacken' %}
<style>
#ProductGridWrapper {
  min-width: 0;
}
#ProductGridContainer > .iq-jv-jump {
  display: none;
}
</style>
{% endif %}

